+  snapshot_workspace_recording(tracking, directory)
+  if !operation_recording(tracking) {
+    return (false, [])
+  }
+  guard saved_workspace_secrets(tracking) is Some(secrets) else {
+    suppress_workspace_recording(tracking)
+    return (false, [])
+  }
+  save_diagnostic(
+    stage,
+    "failed",
+    error_type="saved_state_invalid",
+    phase~,
+    tunnel_directory=directory,
+    error_message=diagnostic_error(error),
+    protected_secrets=secrets,
+    recording=true,
+  )
