@@ -1,3 +1,310 @@
+///|
+priv struct DiagnosticRecordingHealth {
+  mut dropped : Int32
+  mut first_dropped : UInt64
+  mut last_dropped : UInt64
+  mut reason : String
+  mut phase : String
+  mut os_errno : Int32?
+  mut warned : Bool
+  mut incident : Bool
+  mut incident_serial : UInt64
+}
+
+///|
+let diagnostic_recording_health : DiagnosticRecordingHealth = {
+  dropped: 0,
+  first_dropped: 0,
+  last_dropped: 0,
+  reason: "",
+  phase: "",
+  os_errno: None,
+  warned: false,
+  incident: false,
+  incident_serial: 0,
+}
+
+///|
+let diagnostic_workspace_environments : Map[String, Map[String, String]] = Map([])
+
+///|
+fn diagnostic_health_snapshot() -> Json {
+  if diagnostic_recording_health.incident ||
+    diagnostic_recording_health.dropped > 0 {
+    {
+      "status": "degraded",
+      "reason": diagnostic_recording_health.reason,
+      "phase": diagnostic_recording_health.phase,
+    }
+  } else {
+    { "status": "healthy" }
+  }
+}
+
+///|
+async fn publish_diagnostic_health() -> Unit {
+  guard @env.args() is [_, "--supervisor", ..] else { return }
+  @async.with_timeout(10, async fn() {
+    let directory = adapter_state_home()
+    let path = directory + "/diagnostic-health.json"
+    if !diagnostic_recording_health.incident &&
+      diagnostic_recording_health.dropped == 0 {
+      @fs.remove(path) catch {
+        _ => ()
+      }
+      return
+    }
+    let temporary = directory +
+      "/diagnostic-health." +
+      proxy_pid().to_string() +
+      ".tmp"
+    defer (@fs.remove(temporary) catch { _ => () })
+    @fs.write_file(
+      temporary,
+      diagnostic_health_snapshot().stringify(),
+      permission=0o600,
+    )
+    @fs.rename(temporary, path, replace=true)
+  }) catch {
+    _ => ()
+  }
+}
+
+///|
+async fn diagnostic_recording_warning(
+  reason : String,
+  phase~ : String = "",
+  os_errno? : Int32,
+) -> Unit {
+  let publish = !diagnostic_recording_health.incident ||
+    diagnostic_recording_health.reason != reason ||
+    diagnostic_recording_health.phase != phase
+  diagnostic_recording_health.incident = true
+  diagnostic_recording_health.incident_serial += 1
+  if diagnostic_recording_health.dropped == 0 {
+    diagnostic_recording_health.reason = reason
+    diagnostic_recording_health.phase = phase
+    diagnostic_recording_health.os_errno = os_errno
+  }
+  if publish {
+    publish_diagnostic_health()
+  }
+  if !diagnostic_recording_health.warned {
+    diagnostic_recording_health.warned = true
+    @async.with_timeout(10, async fn() {
+      @stdio.stderr.write(
+        "orca-env-devsy: warning: diagnostic recording is unavailable (" +
+        reason +
+        (if phase == "" { "" } else { ", phase=" + phase }) +
+        os_errno.map(code => ", errno=" + code.to_string()).unwrap_or("") +
+        ")\n",
+      )
+    }) catch {
+      _ => ()
+    }
+  }
+}
+
+///|
+async fn diagnostic_recording_failed(
+  reason : String,
+  phase~ : String = "",
+  os_errno? : Int32,
+  event_time? : UInt64,
+) -> Unit {
+  let time = event_time.unwrap_or(@env.now())
+  let health_changed = diagnostic_recording_health.reason != reason ||
+    diagnostic_recording_health.phase != phase
+  if diagnostic_recording_health.dropped == 0 {
+    diagnostic_recording_health.first_dropped = time
+    diagnostic_recording_health.last_dropped = time
+  } else {
+    if time < diagnostic_recording_health.first_dropped {
+      diagnostic_recording_health.first_dropped = time
+    }
+    if time > diagnostic_recording_health.last_dropped {
+      diagnostic_recording_health.last_dropped = time
+    }
+  }
+  diagnostic_recording_health.dropped += 1
+  diagnostic_recording_health.reason = reason
+  diagnostic_recording_health.phase = phase
+  diagnostic_recording_health.os_errno = os_errno
+  diagnostic_recording_warning(reason, phase~, os_errno?)
+  if health_changed {
+    publish_diagnostic_health()
+  }
+}
+
+///|
+priv struct PendingDiagnostic {
+  event : Json
+  failed : Bool
+  time : UInt64
+}
+
+///|
+let diagnostic_pending : Array[PendingDiagnostic] = []
+
+///|
+let diagnostic_pending_inflight : Ref[Int32] = { val: 0, }
+
+///|
+let diagnostic_write_active : Ref[Bool] = { val: false, }
+
+///|
+let diagnostic_operation_counter : Ref[UInt64] = { val: 0, }
+
+///|
+fn diagnostic_recording_event(status : String, reason : String) -> Json {
+  {
+    "stage": "diagnostic-recording",
+    "status": status,
+    "errorType": reason,
+    "completeness": "partial",
+    "time": @env.now().to_string(),
+    "runId": recording_run_id,
+    "adapterVersion": version,
+  }
+}
+
+///|
+fn diagnostic_json(
+  value : Json,
+  environment : Map[String, String],
+  protected_secrets : Array[String],
+  truncated : Ref[Bool],
+  depth : Int32,
+  stable_activity~ : Bool = false,
+) -> Json {
+  if depth >= 64 {
+    truncated.val = true
+    return Json::string("[nested evidence omitted]")
+  }
+  match value {
+    Json::Object(values) => {
+      let result = Json::empty_object()
+      for name, item in values {
+        let key = name.to_lower().replace_all(old="_", new="")
+        let safe_name = if stable_activity &&
+          [
+            "schemaVersion", "observedAt", "activity", "reason", "terminals", "chats",
+            "errors", "worktreeId", "agent", "type", "state", "programState", "sessionId",
+            "workspaceId", "source", "code", "id", "uid", "context", "provider",
+            "identityVerified", "vmStatus", "outcome", "evidence", "evidenceTruncated",
+            "workspaces", "discoveryErrors", "action", "failed", "detailsTruncated",
+            "error", "autoStop",
+          ].contains(name) {
+          name
+        } else {
+          diagnostic_text(name, environment~, protected_secrets~)
+        }
+        if field(result, safe_name) is Some(_) {
+          truncated.val = true
+          continue
+        }
+        if safe_name.has_suffix("\n[error details incomplete or truncated]") {
+          truncated.val = true
+        }
+        set_field(
+          result,
+          safe_name,
+          if credential_field(name) || key == "pairingcode" {
+            Json::string("[redacted]")
+          } else if stable_activity &&
+            name == "activity" &&
+            (
+              item == Json::string("idle") ||
+              item == Json::string("active") ||
+              item == Json::string("unknown")
