+///|
+fn redact_known_values(text : String, secrets : Array[String]) -> String {
+  let chars = text.iter().to_array()
+  let values : Array[Array[Char]] = []
+  for secret in secrets {
+    if secret.length() <= text.length() {
+      values.push(secret.iter().to_array())
+    }
+  }
+  let result = @buffer.Buffer(size_hint=text.length())
+  let mut i = 0
+  while i < chars.length() {
+    if i + 10 <= chars.length() &&
+      character_text(chars, i, i + 10) == "[redacted]" {
+      result.write_string_utf8("[redacted]")
+      i += 10
+      continue
+    }
+    let mut matched = 0
+    for index in 0..<values.length() {
+      let value = values[index]
+      let mut matches = value.length() > 0 &&
+        i + value.length() <= chars.length()
+      if matches {
+        for j in 0..<value.length() {
+          if chars[i + j] != value[j] {
+            matches = false
+            break
+          }
+        }
+      }
+      if matches {
+        matched = value.length()
+        break
+      }
+    }
+    if matched > 0 {
+      result.write_string_utf8("[redacted]")
+      i += matched
+    } else {
+      result.write_char_utf8(chars[i])
+      i += 1
+    }
+  }
+  @utf8.decode_lossy(result.to_bytes())
+}
