///|
fn recording_from_environment(environment : Json) -> Bool {
  match environment {
    Json::Object(values) =>
      match values.get("ORCA_ENV_DEVSY_RECORDING") {
        None => true
        Some(Json::String(value)) => value != "0"
        _ => false
      }
    _ => false
  }
}

///|
fn workspace_recording(state : Json) -> Bool {
  match field(state, "diagnosticRecording") {
    Some(value) if value == Json::boolean(false) => return false
    Some(value) if value == Json::boolean(true) => return true
    _ => ()
  }
  match field(state, "executionEnvironment") {
    Some(environment) => recording_from_environment(environment)
    None => @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0")
  }
}

///|
async fn diagnostic_read_file(path : String, limit : Int64) -> String? {
  @async.with_timeout(250, async fn() {
    guard @fs.kind(path, follow_symlink=false) == @fs.FileKind::Regular &&
      @fs.file_size(path) <= limit else {
      return None
    }
    Some(@fs.read_file(path).text())
  }) catch {
    error => if @async.is_being_cancelled() { raise error } else { None }
  }
}

///|
async fn snapshot_workspace_recording(state : Json, directory : String) -> Unit {
  let enabled = if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
    false
  } else {
    let value = try {
      guard diagnostic_read_file(directory + "/environment.json", 4194304L)
        is Some(raw) else {
        raise AdapterError("Saved recording settings unavailable")
      }
      let environment = @json.parse(raw)
      guard environment is Json::Object(_) else {
        raise AdapterError("Invalid saved recording settings")
      }
      Some(recording_from_environment(environment))
    } catch {
      error => if @async.is_being_cancelled() { raise error } else { None }
    }
    if value is None {
      diagnostic_recording_warning(
        "workspace_recording_unknown",
        phase="configuration",
      )
    }
    value.unwrap_or(false)
  }
  set_field(state, "diagnosticRecording", Json::boolean(enabled))
}

///|
async fn saved_workspace_secrets(
  state : Json,
  for_output~ : Bool = false,
) -> Array[String]? {
  if !for_output && !state_recording(state) {
    return Some([])
  }
  try {
    let directory = required(state, "tunnelDirectory")
    guard diagnostic_read_file(directory + "/environment.json", 4194304L)
      is Some(raw) else {
      return None
    }
    let saved = @json.parse(raw)
    guard saved is Json::Object(values) else { return None }
    let environment : Map[String, String] = Map([])
    for name, value in values {
      guard value is Json::String(value) else { return None }
      environment.set(name, value)
    }
    let secrets = Progress::new("diagnostic-evidence", environment~).secrets
    guard workspace_pairing_secrets(state) is Some(pairing) else { return None }
    for value in pairing {
      secrets.push(value)
    }
    Some(secrets)
  } catch {
    error => if @async.is_being_cancelled() { raise error } else { None }
  }
}

///|
async fn workspace_pairing_value(state : Json) -> String? {
  try {
    let path = required(state, "tunnelDirectory") + "/pairing-code"
    if !@fs.exists(path) {
      return Some("")
    }
    diagnostic_read_file(path, 65536L)
  } catch {
    error => if @async.is_being_cancelled() { raise error } else { None }
  }
}

///|
async fn workspace_pairing_secrets(state : Json) -> Array[String]? {
  guard workspace_pairing_value(state) is Some(pairing) else { return None }
  let secrets = if pairing == "" { [] } else { [pairing] }
  for line in pairing.split("\n") {
    if line.trim() != "" && line.length() < pairing.length() {
      secrets.push(line.to_owned())
    }
  }
  Some(secrets)
}

///|
async fn workspace_error_detail(state : Json, error : Error) -> String {
  let environment = workspace_environment(state)
  guard saved_workspace_secrets(state, for_output=true) is Some(secrets) else {
    return "Error detail unavailable because workspace protection values could not be read"
  }
  diagnostic_text(
    diagnostic_error(error, environment~),
    environment~,
    protected_secrets=secrets,
  )
}

///|
async fn record_discovery_error(
  stage : String,
  directory : String,
  phase : String,
  error : Error,
) -> (Bool, Array[String]) {
  let tracking : Json = { "tunnelDirectory": directory }
  snapshot_workspace_recording(tracking, directory)
  if !operation_recording(tracking) {
    return (false, [])
  }
  guard saved_workspace_secrets(tracking) is Some(secrets) else {
    suppress_workspace_recording(tracking)
    return (false, [])
  }
  save_diagnostic(
    stage,
    "failed",
    error_type="saved_state_invalid",
    phase~,
    tunnel_directory=directory,
    error_message=diagnostic_error(error),
    protected_secrets=secrets,
    recording=true,
  )
  (true, secrets)
}

///|
async fn suppress_workspace_recording(state : Json) -> Unit {
  if state_recording(state) {
    diagnostic_recording_failed(
      "protected_values_unavailable",
      phase="redaction",
    )
  }
  set_field(state, "diagnosticRecording", Json::boolean(false))
}

///|
fn operation_recording(state : Json) -> Bool {
  @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0") &&
  workspace_recording(state)
}

///|
fn state_recording(state : Json) -> Bool {
  match @env.args() {
    [_, "--supervisor" | "--ssh-proxy", ..] => workspace_recording(state)
    _ => operation_recording(state)
  }
}

///|
priv struct DiagnosticRecordingHealth {
  mut dropped : Int32
  mut first_dropped : UInt64
  mut last_dropped : UInt64
  mut reason : String
  mut phase : String
  mut os_errno : Int32?
  mut warned : Bool
  mut incident : Bool
  mut incident_serial : UInt64
}

///|
let diagnostic_recording_health : DiagnosticRecordingHealth = {
  dropped: 0,
  first_dropped: 0,
  last_dropped: 0,
  reason: "",
  phase: "",
  os_errno: None,
  warned: false,
  incident: false,
  incident_serial: 0,
}

///|
let diagnostic_workspace_environments : Map[String, Map[String, String]] = Map([])

///|
fn diagnostic_health_snapshot() -> Json {
  if diagnostic_recording_health.incident ||
    diagnostic_recording_health.dropped > 0 {
    {
      "status": "degraded",
      "reason": diagnostic_recording_health.reason,
      "phase": diagnostic_recording_health.phase,
    }
  } else {
    { "status": "healthy" }
  }
}

///|
async fn publish_diagnostic_health() -> Unit {
  guard @env.args() is [_, "--supervisor", ..] else { return }
  @async.with_timeout(10, async fn() {
    let directory = adapter_state_home()
    let path = directory + "/diagnostic-health.json"
    if !diagnostic_recording_health.incident &&
      diagnostic_recording_health.dropped == 0 {
      @fs.remove(path) catch {
        _ => ()
      }
      return
    }
    let temporary = directory +
      "/diagnostic-health." +
      proxy_pid().to_string() +
      ".tmp"
    defer (@fs.remove(temporary) catch { _ => () })
    @fs.write_file(
      temporary,
      diagnostic_health_snapshot().stringify(),
      permission=0o600,
    )
    @fs.rename(temporary, path, replace=true)
  }) catch {
    _ => ()
  }
}

///|
async fn diagnostic_recording_warning(
  reason : String,
  phase~ : String = "",
  os_errno? : Int32,
) -> Unit {
  let publish = !diagnostic_recording_health.incident ||
    diagnostic_recording_health.reason != reason ||
    diagnostic_recording_health.phase != phase
  diagnostic_recording_health.incident = true
  diagnostic_recording_health.incident_serial += 1
  if diagnostic_recording_health.dropped == 0 {
    diagnostic_recording_health.reason = reason
    diagnostic_recording_health.phase = phase
    diagnostic_recording_health.os_errno = os_errno
  }
  if publish {
    publish_diagnostic_health()
  }
  if !diagnostic_recording_health.warned {
    diagnostic_recording_health.warned = true
    @async.with_timeout(10, async fn() {
      @stdio.stderr.write(
        "orca-env-devsy: warning: diagnostic recording is unavailable (" +
        reason +
        (if phase == "" { "" } else { ", phase=" + phase }) +
        os_errno.map(code => ", errno=" + code.to_string()).unwrap_or("") +
        ")\n",
      )
    }) catch {
      _ => ()
    }
  }
}

///|
async fn diagnostic_recording_failed(
  reason : String,
  phase~ : String = "",
  os_errno? : Int32,
  event_time? : UInt64,
) -> Unit {
  let time = event_time.unwrap_or(@env.now())
  let health_changed = diagnostic_recording_health.reason != reason ||
    diagnostic_recording_health.phase != phase
  if diagnostic_recording_health.dropped == 0 {
    diagnostic_recording_health.first_dropped = time
    diagnostic_recording_health.last_dropped = time
  } else {
    if time < diagnostic_recording_health.first_dropped {
      diagnostic_recording_health.first_dropped = time
    }
    if time > diagnostic_recording_health.last_dropped {
      diagnostic_recording_health.last_dropped = time
    }
  }
  diagnostic_recording_health.dropped += 1
  diagnostic_recording_health.reason = reason
  diagnostic_recording_health.phase = phase
  diagnostic_recording_health.os_errno = os_errno
  diagnostic_recording_warning(reason, phase~, os_errno?)
  if health_changed {
    publish_diagnostic_health()
  }
}

///|
priv struct PendingDiagnostic {
  event : Json
  failed : Bool
  time : UInt64
}

///|
let diagnostic_pending : Array[PendingDiagnostic] = []

///|
let diagnostic_pending_inflight : Ref[Int32] = { val: 0, }

///|
let diagnostic_write_active : Ref[Bool] = { val: false, }

///|
let diagnostic_operation_counter : Ref[UInt64] = { val: 0, }

///|
fn diagnostic_recording_event(status : String, reason : String) -> Json {
  {
    "stage": "diagnostic-recording",
    "status": status,
    "errorType": reason,
    "completeness": "partial",
    "time": @env.now().to_string(),
    "runId": recording_run_id,
    "adapterVersion": version,
  }
}

///|
fn diagnostic_json(
  value : Json,
  environment : Map[String, String],
  protected_secrets : Array[String],
  truncated : Ref[Bool],
  depth : Int32,
  stable_activity~ : Bool = false,
) -> Json {
  if depth >= 64 {
    truncated.val = true
    return Json::string("[nested evidence omitted]")
  }
  match value {
    Json::Object(values) => {
      let result = Json::empty_object()
      for name, item in values {
        let key = name.to_lower().replace_all(old="_", new="")
        let safe_name = if stable_activity &&
          [
            "schemaVersion", "observedAt", "activity", "reason", "terminals", "chats",
            "errors", "worktreeId", "agent", "type", "state", "programState", "sessionId",
            "workspaceId", "source", "code", "id", "uid", "context", "provider",
            "identityVerified", "vmStatus", "outcome", "evidence", "evidenceTruncated",
            "workspaces", "discoveryErrors", "action", "failed", "detailsTruncated",
            "error", "autoStop",
          ].contains(name) {
          name
        } else {
          diagnostic_text(name, environment~, protected_secrets~)
        }
        if field(result, safe_name) is Some(_) {
          truncated.val = true
          continue
        }
        if safe_name.has_suffix("\n[error details incomplete or truncated]") {
          truncated.val = true
        }
        set_field(
          result,
          safe_name,
          if credential_field(name) || key == "pairingcode" {
            Json::string("[redacted]")
          } else if stable_activity &&
            name == "activity" &&
            (
              item == Json::string("idle") ||
              item == Json::string("active") ||
              item == Json::string("unknown")
            ) {
            item
          } else {
            diagnostic_json(
              item,
              environment,
              protected_secrets,
              truncated,
              depth + 1,
              stable_activity~,
            )
          },
        )
      }
      result
    }
    Json::Array(values) =>
      Json::array(
        values.map(item => {
          diagnostic_json(
            item,
            environment,
            protected_secrets,
            truncated,
            depth + 1,
            stable_activity~,
          )
        }),
      )
    Json::String(text) => {
