///|
async fn command_result(
  program : String,
  args : Array[String],
  stage : String,
  environment? : Map[String, String],
  cwd? : StringView,
  target? : String,
  recording_override? : Bool,
) -> (Int32, String, String) {
  let recording = recording_override.unwrap_or(
    environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
    Some("0"),
  )
