    let secrets = Progress::new("diagnostic-evidence", environment~).secrets
    guard workspace_pairing_secrets(state) is Some(pairing) else { return None }
    for value in pairing {
      secrets.push(value)
    }
    Some(secrets)
  } catch {
    error => if @async.is_being_cancelled() { raise error } else { None }
  }
}

///|
async fn workspace_pairing_value(state : Json) -> String? {
  try {
    let path = required(state, "tunnelDirectory") + "/pairing-code"
    if !@fs.exists(path) {
      return Some("")
    }
    diagnostic_read_file(path, 65536L)
  } catch {
    error => if @async.is_being_cancelled() { raise error } else { None }
  }
