          let (allowed, secrets) = record_discovery_error(
            "bulk-discovery", directory, discovery_phase, error,
          )
          discovery_recording = discovery_recording && allowed
          for secret in secrets {
            discovery_secrets.push(secret)
          }
        }
      }
    }
  }
  recording_allowed.val = recording_allowed.val &&
    discovery_recording &&
    states.iter().all(workspace_recording)
  let keys : Map[String, Int32] = Map([])
  for state in states {
    let key = required(state, "context") + ":" + required(state, "workspaceUid")
    keys.set(key, keys.get(key).unwrap_or(0) + 1)
  }
  let results : Array[Json] = []
  let permits = @async.Semaphore(options.jobs)
  @async.with_task_group(async fn(group) {
    for state in states {
      let key = required(state, "context") +
        ":" +
        required(state, "workspaceUid")
      if keys.get(key) != Some(1) {
        discovery_errors.push({
          "savedState": required(state, "tunnelDirectory"),
          "reason": "duplicate_saved_identity",
        })
        continue
      }
      permits.acquire()
      group.spawn_bg(async fn() {
        defer permits.release()
        if bulk_one(mode, state, options) is Some(result) {
          results.push(result)
        }
      })
    }
  })
  results.sort_by((a, b) => {
    let a_id = match field(a, "id") {
      Some(Json::String(id)) => id
      _ => ""
    }
    let b_id = match field(b, "id") {
      Some(Json::String(id)) => id
      _ => ""
    }
    a_id.compare(b_id)
  })
  let failures = results
    .filter(r => field(r, "outcome") == Some(Json::string("failed")))
    .length()
  let output : Json = {
    "schemaVersion": 1,
    "action": mode,
    "provider": options.provider,
    "workspaces": results,
    "failed": failures,
    "discoveryErrors": discovery_errors,
  }
  @stdio.stdout.write(output.stringify(indent=2) + "\n")
  recording_allowed.val = recording_allowed.val &&
    states.iter().all(workspace_recording)
  let secrets : Array[String] = [] + discovery_secrets
  for state in states {
    match saved_workspace_secrets(state) {
      Some(values) =>
        for secret in values {
          secrets.push(secret)
        }
      None => {
        suppress_workspace_recording(state)
        recording_allowed.val = false
      }
    }
  }
  save_diagnostic(
    "bulk",
    if failures > 0 {
      "failed"
    } else if !discovery_errors.is_empty() {
      "partial"
    } else {
      "success"
    },
    error_type?=if !discovery_errors.is_empty() {
      Some("saved_state_invalid")
    } else {
      None
    },
    evidence=output,
    evidence_incomplete=results
      .iter()
      .any(result => {
        field(result, "evidenceTruncated") == Some(Json::boolean(true))
      }),
    evidence_stable_activity=true,
    protected_secrets=secrets,
    recording=recording_allowed.val,
  )

  failures
}

