pub async fn supervisor(
  directory : String,
  initial_workspace? : String,
) -> Unit {
  let startup_hold : Ref[@fs.File?] = { val: None, }
  defer (if startup_hold.val is Some(held) { held.close() })
  let mut lock : @fs.File? = None
  defer (if lock is Some(held) { held.close() })
  defer @async.protect_from_cancel(async fn() { flush_diagnostic_recording() })
  let mut failure_recorded = false
  errdefer (if !failure_recorded && @async.is_being_cancelled() {
    @async.protect_from_cancel(async fn() {
      save_diagnostic("supervisor", "cancelled", error_type="cancelled")
    })
  })
  let failure = try {
    guard directory == adapter_state_home() else {
      raise AdapterError("Supervisor state directory mismatch")
    }
    let held = @fs.open(
      directory + "/supervisor.lock",
      mode=ReadWrite,
      create_mode=OpenOrCreate,
      permission=0o600,
    )
    lock = Some(held)
    if !held.try_lock(Exclusive) {
      return
    }
    supervisor_inner(directory, startup_hold, initial_workspace?)
    None
  } catch {
    error => Some(error)
  }
  if failure is Some(error) {
    failure_recorded = true
    save_command_failure("supervisor", error)
    raise error
  }
}

