///|
async fn worker_alive(directory : String) -> Bool {
  let lock = @fs.open(
    directory + "/worker.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  !lock.try_lock(Exclusive)
}

///|
async fn tunnel_status(
  directory : String,
  status : String,
  recording? : Bool,
) -> Unit {
  let value : Json = { "status": status, "runId": recording_run_id }
  @fs.write_file(directory + "/status.tmp", value.stringify(), permission=0o600)
  @fs.rename(
    directory + "/status.tmp",
    directory + "/status.json",
    replace=true,
  )
  save_diagnostic("orca-tunnel", status, tunnel_directory=directory, recording?)
}

///|
async fn connection_failure(
  directory : String,
  names : Array[String],
) -> String? {
  for name in names {
    let event = @json.parse(@fs.read_file(directory + "/" + name).text()) catch {
      _ => Json::null()
    }
    if field(event, "detail") is Some(Json::String(detail)) && detail != "" {
      return Some(detail)
    }
  }
  None
}

///|
async fn save_connection_failure(
  directory : String,
  name : String,
  detail : String,
) -> Unit {
  let value : Json = { "detail": detail }
  let temporary = directory + "/" + name + ".tmp"
  @fs.write_file(temporary, value.stringify(), permission=0o600)
  @fs.rename(temporary, directory + "/" + name, replace=true)
}

///|
async fn adapter_executable() -> String {
  let name = @env.args()[0]
  if name.contains("/") {
    return @fs.realpath(name)
  }
  for directory in @env.get_env_var("PATH").unwrap_or("").split(":") {
    let path = directory.to_owned() + "/" + name
    if @fs.exists(path) {
      return @fs.realpath(path)
    }
  }
  raise AdapterError("Adapter executable is unavailable for tunnel recovery")
}

///|
async fn saved_proxy_executable() -> String {
  let directory = adapter_state_home()
  @fs.mkdir(directory, recursive=true, permission=0o700, allow_exist=true)
  let lock = @fs.open(
    directory + "/launcher.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  @async.with_timeout(10000, async fn() {
    while !lock.try_lock(Exclusive) {
      @async.sleep(10)
    }
  })
  let target = directory + "/ssh-proxy-adapter"
  let executable = adapter_executable()
  if executable == target {
  guard failures == 0 else {
    raise AdapterError(
      "Some connections could not be recovered; other targets were attempted",
    )
  }
  save_diagnostic("recover", "success")
}

///|
async fn connection_operation_lock(
  state : Json,
  validate~ : Bool = true,
) -> @fs.File {
  let directory = required(state, "tunnelDirectory")
  @fs.mkdir(directory, recursive=true, permission=0o700, allow_exist=true)
  let lock = @fs.open(
    directory + "/operation.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  errdefer lock.close()
  @async.with_timeout(60000, async fn() {
    while !lock.try_lock(Exclusive) {
      @async.sleep(100)
    }
  })
  if validate {
    validate_connection_owner(state)
  }
  lock
}

///|
async fn validate_connection_owner(state : Json) -> Unit {
  @async.with_timeout(10000, async fn() {
    match workspace(state) {
      Some(current) if field(current, "uid") == field(state, "workspaceUid") =>
        ()
      None => ()
      _ => raise AdapterError("Workspace replaced during lifecycle operation")
    }
  })
}

///|
async fn pause_request(directory : String) -> String? {
  Some(@fs.read_file(directory + "/paused").text()) catch {
    error => if !@fs.exists(directory + "/paused") { None } else { raise error }
  }
}

///|
async fn pause_tunnel(state : Json) -> Unit {
  let directory = required(state, "tunnelDirectory")
  errdefer unpause_tunnel(state)
///|
async fn monitor_wait(directory : String, delay : Int32) -> Unit {
  for elapsed = 0
      elapsed < delay && @fs.exists(directory + "/enabled")
      elapsed = elapsed + 100 {
    if @fs.exists(directory + "/probe-request") ||
      @fs.exists(directory + "/paused") {
      return
    }
    @async.sleep(100)
  }
}

///|
async fn recover_connection(
  state : Json,
  restart~ : Bool = false,
  deadline? : UInt64,
  saved_environment~ : Bool = false,
) -> Unit {
  let operation = connection_operation_lock(state, validate=false)
  defer operation.close()
  let directory = required(state, "tunnelDirectory")
  if saved_environment {
    let environment = @json.parse(
      @fs.read_file(directory + "/environment.json").text(),
    )
    guard environment is Json::Object(_) else {
      raise AdapterError("Invalid saved workspace environment")
    }
    set_field(state, "executionEnvironment", environment)
    set_field(
      state,
      "diagnosticRecording",
      Json::boolean(recording_from_environment(environment)),
    )
  }
  let deadline = deadline.unwrap_or(connection_deadline())
  connection_timeout(deadline, async fn() {
    let current = workspace(state)
    guard current is Some(current) &&
      field(current, "uid") == field(state, "workspaceUid") else {
      save_diagnostic(
        "recover",
        "ownership-error",
        tunnel_directory=directory,
        environment=workspace_environment(state),
        recording=state_recording(state),
      )
      raise AdapterError("Tunnel workspace ownership changed")
    }
    let status = workspace_status(state)
    save_diagnostic(
      "recover-workspace",
      status,
      tunnel_directory=directory,
      environment=workspace_environment(state),
      recording=state_recording(state),
    )
    match status {
      "Running" => ()
      "Stopped" => {
        progress_message(
          required(state, "workspaceId") +
          ": workspace stopped; recovery skipped",
        )
        return
      }
      "Busy" =>
        raise AdapterError(
          "Workspace is Busy; wait for workspace up to finish before recover",
        )
      _ => raise AdapterError("Workspace is missing")
    }
    @fs.mkdir(directory, recursive=true, permission=0o700, allow_exist=true)
    let lock = @fs.open(
      directory + "/recovery.lock",
      mode=ReadWrite,
      create_mode=OpenOrCreate,
      permission=0o600,
    )
    defer lock.close()
    @async.with_timeout(30000, async fn() {
      while !lock.try_lock(Exclusive) {
        @async.sleep(100)
      }
    })
    let port = match field(state, "localPort") {
      Some(Json::Number(value, ..)) if value >= 1 &&
        value <= 65535 &&
        value == value.to_int().to_double() => Some(value.to_int())
      None if field(state, "connection") == Some(Json::string("ssh")) => None
      _ => raise AdapterError("Invalid saved tunnel port")
    }
    save_diagnostic(
      "recover-worker",
      if restart {
        "restart"
      } else if worker_alive(directory) {
        "reuse"
      } else {
        "restore"
      },
      tunnel_directory=directory,
      environment=workspace_environment(state),
      recording=state_recording(state),
    )
    ensure_ssh_worker(state, port, deadline~, restart~)
    if required(state, "connection") == "orca-server" {
      ignore(recover_server(state))
    }
    save_diagnostic(
      "recover",
      "success",
      tunnel_directory=directory,
      environment=workspace_environment(state),
      recording=state_recording(state),
    )
  })
}

  output
}

///|
fn devsy_args(state : Json) -> Array[String] {
  let args = []
  for name in ["home", "context", "provider"] {
    if field(state, name) is Some(Json::String(value)) {
      args.push("--" + name)
      args.push(value)
    }
  }
  args
}

///|
fn workspace_environment(state : Json) -> Map[String, String] {
  let environment = match field(state, "executionEnvironment") {
    Some(Json::Object(values)) => {
      let result : Map[String, String] = Map([])
      for (name, value) in values {
        if value is Json::String(value) {
          result.set(name, value)
        }
      }
      result
    }
    _ => @env.get_env_vars()
  }
  for name in location_variables {
    match field(field(state, "devsyEnv").unwrap_or(Json::null()), name) {
      Some(Json::String(value)) => environment.set(name, value)
      _ => environment.remove(name)
    }
  }
  environment
}

///|
fn workspace_directory(state : Json) -> String? {
  match field(state, "hostDirectory") {
    Some(Json::String(value)) => Some(value)
    _ => None
  }
}

