///|
async fn diagnostic_read_file(path : String, limit : Int64) -> String? {
  @async.with_timeout(250, async fn() {
    guard @fs.kind(path, follow_symlink=false) == @fs.FileKind::Regular &&
      @fs.file_size(path) <= limit else {
      return None
    }
    Some(@fs.read_file(path).text())
  }) catch {
    error => if @async.is_being_cancelled() { raise error } else { None }
  }
}

///|
async fn snapshot_workspace_recording(state : Json, directory : String) -> Unit {
  let enabled = if @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") == Some("0") {
    false
  } else {
    let value = try {
      guard diagnostic_read_file(directory + "/environment.json", 4194304L)
        is Some(raw) else {
        raise AdapterError("Saved recording settings unavailable")
      }
      let environment = @json.parse(raw)
      guard environment is Json::Object(_) else {
        raise AdapterError("Invalid saved recording settings")
      }
      Some(recording_from_environment(environment))
    } catch {
      error => if @async.is_being_cancelled() { raise error } else { None }
    }
    if value is None {
      diagnostic_recording_warning(
        "workspace_recording_unknown",
        phase="configuration",
      )
    }
    value.unwrap_or(false)
  }
  set_field(state, "diagnosticRecording", Json::boolean(enabled))
}

///|
async fn saved_workspace_secrets(
  state : Json,
  for_output~ : Bool = false,
) -> Array[String]? {
  if !for_output && !state_recording(state) {
    return Some([])
  }
  try {
    let directory = required(state, "tunnelDirectory")
    guard diagnostic_read_file(directory + "/environment.json", 4194304L)
      is Some(raw) else {
      return None
    }
    let saved = @json.parse(raw)
    guard saved is Json::Object(values) else { return None }
    let environment : Map[String, String] = Map([])
    for name, value in values {
      guard value is Json::String(value) else { return None }
      environment.set(name, value)
    }
    let secrets = Progress::new("diagnostic-evidence", environment~).secrets
    guard workspace_pairing_secrets(state) is Some(pairing) else { return None }
    for value in pairing {
      secrets.push(value)
    }
    Some(secrets)
  } catch {
    error => if @async.is_being_cancelled() { raise error } else { None }
  }
}

///|
async fn workspace_pairing_value(state : Json) -> String? {
  try {
    let path = required(state, "tunnelDirectory") + "/pairing-code"
    if !@fs.exists(path) {
      return Some("")
    }
    diagnostic_read_file(path, 65536L)
  } catch {
    error => if @async.is_being_cancelled() { raise error } else { None }
  }
}

///|
async fn workspace_pairing_secrets(state : Json) -> Array[String]? {
  guard workspace_pairing_value(state) is Some(pairing) else { return None }
  let secrets = if pairing == "" { [] } else { [pairing] }
  for line in pairing.split("\n") {
    if line.trim() != "" && line.length() < pairing.length() {
      secrets.push(line.to_owned())
    }
  }
  Some(secrets)
}

///|
async fn workspace_error_detail(state : Json, error : Error) -> String {
  let environment = workspace_environment(state)
  guard saved_workspace_secrets(state, for_output=true) is Some(secrets) else {
    return "Error detail unavailable because workspace protection values could not be read"
  }
  diagnostic_text(
    diagnostic_error(error, environment~),
    environment~,
    protected_secrets=secrets,
  )
}

