///|
test "large protected input retains independent transport errors" {
  let words : Array[String] = []
  for index in 0..<1200 {
    words.push("profile-argument-" + index.to_string())
  }
  let input : Json = {
    "agentArgs": words.join(" "),
    "access_token": "fixture-large-input-secret",
  }
  let detail = diagnostic_output(
    @utf8.encode("SSH connection refused token=fixture-large-input-secret"),
    {},
    protected_input=input.stringify(),
  ).unwrap()
  assert_true(detail.contains("SSH connection refused"), msg=detail)
  assert_false(detail.contains("fixture-large-input-secret"), msg=detail)
  assert_false(detail.contains("output omitted"), msg=detail)
  let truncated = diagnostic_output(
    @utf8.encode("SSH connection refused token=fixture-large-input-sec"),
    {},
    protected_input=input.stringify(),
    omitted=true,
  ).unwrap()
  assert_true(truncated.contains("SSH connection refused"), msg=truncated)
  assert_false(truncated.contains("fixture-large-input-sec"), msg=truncated)
  assert_false(truncated.contains("output omitted"), msg=truncated)
}

