      "{\"code\":\"provider temporarily unavailable\",\"access_token\":\"fixture-unstructured-secret\"}",
      "[provider] provider temporarily unavailable fixture-unstructured-secret",
      "{\"error\":{\"reason\":\"provider temporarily unavailable\",\"access_token\":\"fixture-unstructured-secret\"}}",
      "{unexpected provider temporarily unavailable token=fixture-unstructured-secret",
    ] {
    let (status, _, detail) = command_result(
