 377	///|
 378	async fn Progress::line(
 379	  self : Progress,
 380	  line : String,
 381	  statuses~ : Bool,
 382	  messages~ : Bool,
 383	) -> Unit {
 384	  if line.trim() == "" {
 385	    return
 386	  }
 387	  let event = @json.parse(line) catch { _ => Json::null() }
 388	  if field(event, "kind") == Some(Json::string("status")) {
 389	    if field(event, "state") == Some(Json::string("failed")) &&
 390	      field(event, "error") is Some(error) {
 391	      for name in ["message", "hint"] {
 392	        if field(error, name) is Some(Json::String(text)) {
 393	          self.message(
 394	            text,
 395	            debug=false,
 396	            warning=true,
 397	            emit=messages || statuses,
 398	          )
 399	        }
 400	      }
 401	    }
 402	    if statuses || messages {
 403	      self.status(event)
 404	    }
 405	    return
 406	  }
 407	  // Result envelopes and arbitrary structured responses are never log text.
 408	  if field(event, "kind") == Some(Json::string("result")) {
 409	    return
 410	  }
 411	  if event is Json::Object(_) {
 412	    let kind = field(event, "kind")
 413	    guard kind == None ||
 414	      kind == Some(Json::string("log")) ||
 415	      kind == Some(Json::string("error")) else {
 416	      return
 417	    }
 418	    let message = match field(event, "msg") {
 419	      Some(value) => Some(value)
 420	      None =>
 421	        match field(event, "message") {
 422	          Some(value) => Some(value)
 423	          None =>
 424	            match field(event, "error") {
 425	              Some(Json::Object(_) as value) => field(value, "message")
 426	              value => value
 427	            }
 428	        }
 429	    }
 430	    guard message is Some(Json::String(text)) else { return }
 431	    let level = field(event, "level")
 432	    self.message(
 433	      text,
 434	      debug=level == Some(Json::string("debug")) ||
 435	        level == Some(Json::string("trace")),
 436	      warning=kind == Some(Json::string("error")) ||
 437	        level == Some(Json::string("warn")) ||
 438	        level == Some(Json::string("error")),
 439	      emit=messages || (statuses && kind != None),
 440	    )
 441	  } else {
 442	    if event != Json::null() {
 443	      return
 444	    }
 445	    // Malformed JSON and binary output are not a safe free-text fallback.
 446	    let text = line.trim().to_owned()
 447	    if text.has_prefix("[ERROR]") || text.has_prefix("[WARN]") {
 448	      self.message(text, debug=false, warning=true, emit=messages)
 449	      return
 450	    }
 451	    if text.has_prefix("{") || text.has_prefix("[") {
 452	      self.details_truncated = true
 453	      return
 454	    }
 455	    self.message(
 456	      text,
 457	      debug=text.contains(" DEBUG ") ||
 458	        text.contains(" TRACE ") ||
 459	        text.has_prefix("DEBUG ") ||
 460	        text.has_prefix("TRACE "),
 461	      warning=text.contains(" WARN ") ||
 462	        text.contains(" ERROR ") ||
 463	        text.has_prefix("WARN ") ||
 464	        text.has_prefix("ERROR "),
 465	      emit=messages,
 466	    )
 467	  }
 468	}
