 474	  statuses~ : Bool,
 475	  messages~ : Bool,
 476	) -> Unit {
 477	  let event = @json.parse(line) catch { _ => Json::null() }
 478	  if event is Json::Object(_) {
 479	    let kind = field(event, "kind")
 480	    let known = kind == None ||
 481	      kind == Some(Json::string("log")) ||
 482	      kind == Some(Json::string("error")) ||
 483	      kind == Some(Json::string("status"))
 484	    let error = field(event, "error").unwrap_or(Json::null())
 485	    let has_message = field(event, "msg") is Some(Json::String(_)) ||
 486	      field(event, "message") is Some(Json::String(_)) ||
 487	      error is Json::String(_) ||
 488	      field(error, "message") is Some(Json::String(_))
 489	    if kind != Some(Json::string("result")) &&
 490	      (!known || (!has_message && kind != Some(Json::string("status")))) {
 491	      let truncated : Ref[Bool] = { val: false, }
 492	      let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
 493	      if truncated.val {
 494	        self.details_truncated = true
 495	      }
 496	      self.message(safe, debug=false, warning=true, emit=false)
 497	      return
 498	    }
 499	  } else if event == Json::null() &&
 500	    (line.trim().has_prefix("[") || line.trim().has_prefix("{")) {
 501	    self.message(line, debug=false, warning=true, emit=false)
 502	    return
 503	  }
 504	  self.line(line, statuses~, messages~)
