   261	async fn diagnostic_retained_records(file : @fs.File, size : Int64) -> String {
   262	  let length = if size > 262144L { 262144 } else { size.to_int() }
   263	  let bytes = FixedArray::make(length, b'\x00')
   264	  let read = file.read_at(bytes, position=size - length.to_int64())
   265	  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
   266	  let lines = text.split("\n").to_array()
   267	  let kept = FixedArray::make(lines.length(), false)
   268	  let mut remaining = 65536
   269	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
   270	    if i == 0 && size > length.to_int64() {
   271	      continue
   272	    }
   273	    let length = lines[i].length() + 1
   274	    if length <= remaining {
   275	      kept[i] = true
   276	      remaining -= length
   277	    }
   278	  }
   279	  remaining = 65536
   280	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
   281	    if kept[i] || (i == 0 && size > length.to_int64()) {
   282	      continue
   283	    }
   284	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
   285	    let failed = field(event, "errorType") is Some(_) ||
   286	      (match field(event, "status") {
   287	        Some(Json::String(status)) =>
   288	          ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
   289	            status,
   290	          )
   291	        _ => false
   292	      })
   293	    let length = lines[i].length() + 1
   294	    if failed && length <= remaining {
   295	      kept[i] = true
   296	      remaining -= length
   297	    }
   298	  }
   299	  let result = @buffer.Buffer(size_hint=131072)
   300	  for i in 0..<lines.length() {
   301	    if kept[i] {
   302	      result.write_string_utf8(lines[i].to_owned() + "\n")
   303	    }
   304	  }
   305	  @utf8.decode_lossy(result.to_bytes())
   306	}
