async test "diagnostic recording exposes rotation and repairs an incomplete record" {
  for mode in ["rotation", "incomplete"] {
    let (directory, env) = fixture()
    defer cleanup_fixture(directory)
    let root = directory + "/.local/state/orca-env-devsy"
    @fs.mkdir(root, recursive=true)
    let path = root + "/events.jsonl"
    if mode == "rotation" {
      @fs.write_file(
        path,
        "{\"stage\":\"old\"}\n".repeat(12000) +
        "{\"stage\":\"critical\",\"status\":\"failed\",\"errorMessage\":\"original cause\"}\n" +
        "{\"stage\":\"old\"}\n".repeat(8000),
      )
    } else {
      @fs.write_file(path, "{\"stage\":\"old\"}\n{\"stage\":\"partial\"")
    }
    let (status, _, errors) = bulk_fixture_run(
      ["status", "--provider", "fixture-provider"],
      env,
    )
    assert_eq(status, 0, msg=errors)
    let events = fixture_events(directory)
    let markers = events.filter(event => {
      field(event, "stage") == Some(Json::string("diagnostic-recording"))
    })
    assert_eq(markers.length(), 1)
    assert_eq(field(markers[0], "completeness"), Some(Json::string("partial")))
    assert_eq(
      field(markers[0], "errorType"),
      Some(
        Json::string(
          if mode == "rotation" {
            "retention_limit"
          } else {
            "incomplete_record"
          },
        ),
      ),
    )
    assert_eq(
      events
      .iter()
      .any(event => field(event, "stage") == Some(Json::string("old"))),
      true,
    )
    if mode == "rotation" {
      assert_true(
        events
        .iter()
        .any(event => {
          field(event, "stage") == Some(Json::string("critical")) &&
          field(event, "errorMessage") == Some(Json::string("original cause"))
        }),
      )
      assert_true(@fs.file_size(path) <= 262144L)
    }
    assert_true(
      events
      .iter()
      .any(event => {
        field(event, "stage") == Some(Json::string("bulk")) &&
        field(event, "status") == Some(Json::string("success"))
      }),
    )
  }
}

